insert into public.survey_templates (key, title, description, category, schema_json, theme_json, settings_json, visibility) values
('stem-needs', 'Khảo sát nhu cầu chủ đề STEM', 'Thu thập thông tin trường, số lớp theo khối, chủ đề STEM × cấp học và hình thức triển khai.', 'Giáo dục STEM', '{"schemaVersion":1,"sections":[{"id":"s_intro","title":"Giới thiệu","questions":[{"required":false,"id":"c_intro","code":"C_INTRO","type":"instruction","title":"Mục đích khảo sát","description":"Khảo sát nhằm tổng hợp nhu cầu triển khai các chủ đề giáo dục STEM năm học 2026–2027 của các nhà trường, làm cơ sở xây dựng kế hoạch tập huấn, học liệu và thiết bị phù hợp. Thời gian hoàn thành khoảng 7–10 phút.","settings":{"tone":"info"}},{"required":true,"id":"q_consent","code":"CONSENT","type":"consent","title":"Đồng ý xử lý dữ liệu","settings":{"consentText":"Tôi xác nhận thông tin cung cấp là chính xác và đồng ý để KDI Education sử dụng dữ liệu cho mục đích tổng hợp nhu cầu, không chia sẻ cho bên thứ ba."}}]},{"id":"s_school","title":"Thông tin nhà trường","questions":[{"required":true,"id":"q_school","code":"SCHOOL_NAME","type":"short_text","title":"Tên trường","placeholder":"VD: Trường THCS Lê Lợi","reportLabel":"Tên trường"},{"required":true,"id":"q_level","code":"SCHOOL_LEVEL","type":"single_choice","title":"Cấp học","options":[{"id":"o_mn","code":"mn","label":"Mầm non","active":true},{"id":"o_th","code":"th","label":"Tiểu học","active":true},{"id":"o_thcs","code":"thcs","label":"THCS","active":true},{"id":"o_thpt","code":"thpt","label":"THPT","active":true},{"id":"o_lc","code":"lc","label":"Liên cấp","active":true}]},{"required":true,"id":"q_addr","code":"SCHOOL_ADDRESS","type":"address","title":"Địa chỉ trường","settings":{"includeWard":true}},{"required":true,"id":"q_contact","code":"CONTACT","type":"contact","title":"Người phụ trách khảo sát","isPII":true,"settings":{"contactFields":["name","position","phone","email"]}},{"required":false,"id":"q_cls_th","code":"CLASSES_PRIMARY","type":"quantity_by_group","title":"Số lớp theo khối (Tiểu học)","description":"Nhập số lớp hiện có của từng khối.","rows":[{"id":"o_k1","code":"k1","label":"Khối 1","active":true},{"id":"o_k2","code":"k2","label":"Khối 2","active":true},{"id":"o_k3","code":"k3","label":"Khối 3","active":true},{"id":"o_k4","code":"k4","label":"Khối 4","active":true},{"id":"o_k5","code":"k5","label":"Khối 5","active":true}],"validation":{"max":50},"logic":{"visibleIf":{"op":"and","rules":[{"questionId":"q_level","operator":"in","value":["th","lc"]}]}}},{"required":false,"id":"q_cls_thcs","code":"CLASSES_LOWER_SEC","type":"quantity_by_group","title":"Số lớp theo khối (THCS)","rows":[{"id":"o_k6","code":"k6","label":"Khối 6","active":true},{"id":"o_k7","code":"k7","label":"Khối 7","active":true},{"id":"o_k8","code":"k8","label":"Khối 8","active":true},{"id":"o_k9","code":"k9","label":"Khối 9","active":true}],"validation":{"max":50},"logic":{"visibleIf":{"op":"and","rules":[{"questionId":"q_level","operator":"in","value":["thcs","lc"]}]}}},{"required":false,"id":"q_cls_thpt","code":"CLASSES_UPPER_SEC","type":"quantity_by_group","title":"Số lớp theo khối (THPT)","rows":[{"id":"o_k10","code":"k10","label":"Khối 10","active":true},{"id":"o_k11","code":"k11","label":"Khối 11","active":true},{"id":"o_k12","code":"k12","label":"Khối 12","active":true}],"validation":{"max":50},"logic":{"visibleIf":{"op":"and","rules":[{"questionId":"q_level","operator":"in","value":["thpt","lc"]}]}}}]},{"id":"s_need","title":"Nhu cầu chủ đề STEM","questions":[{"required":true,"id":"q_topics","code":"STEM_TOPICS","type":"category_level","title":"Chọn chủ đề STEM nhà trường muốn triển khai và số lớp dự kiến theo cấp","description":"Tích vào ô phù hợp và nhập số lớp dự kiến tham gia.","rows":[{"id":"o_robot","code":"robot","label":"Robotics & lập trình","active":true},{"id":"o_ai","code":"ai","label":"Trí tuệ nhân tạo & khoa học dữ liệu","active":true},{"id":"o_energy","code":"energy","label":"Năng lượng tái tạo","active":true},{"id":"o_env","code":"env","label":"Môi trường & biến đổi khí hậu","active":true},{"id":"o_mech","code":"mech","label":"Cơ khí – mô hình kỹ thuật","active":true},{"id":"o_d3","code":"d3","label":"Thiết kế & in 3D","active":true},{"id":"o_astro","code":"astro","label":"Thiên văn học","active":true},{"id":"o_bio","code":"bio","label":"Sinh học & sức khỏe","active":true}],"options":[{"id":"o_th","code":"th","label":"Tiểu học","active":true},{"id":"o_thcs","code":"thcs","label":"THCS","active":true},{"id":"o_thpt","code":"thpt","label":"THPT","active":true}],"settings":{"withQuantity":true,"quantityLabel":"Số lớp"}},{"required":true,"id":"q_mode","code":"DELIVERY_MODE","type":"multiple_choice","title":"Hình thức triển khai mong muốn","options":[{"id":"o_curr","code":"curr","label":"Lồng ghép chính khóa","active":true},{"id":"o_club","code":"club","label":"Câu lạc bộ STEM","active":true},{"id":"o_extra","code":"extra","label":"Hoạt động ngoại khóa","active":true},{"id":"o_visit","code":"visit","label":"Trải nghiệm tại trung tâm KDI","active":true}],"settings":{"allowOther":true,"otherLabel":"Khác"}},{"required":false,"id":"q_time","code":"TIMING","type":"multiple_choice","title":"Thời điểm triển khai","options":[{"id":"o_hk1","code":"hk1","label":"Học kỳ I","active":true},{"id":"o_hk2","code":"hk2","label":"Học kỳ II","active":true},{"id":"o_summer","code":"summer","label":"Hè 2027","active":true}]},{"required":true,"id":"q_lab","code":"HAS_STEM_LAB","type":"yes_no","title":"Trường đã có phòng học STEM chưa?","options":[{"id":"o_yes","code":"yes","label":"Có","active":true},{"id":"o_no","code":"no","label":"Chưa","active":true}]},{"required":true,"id":"q_lab_support","code":"LAB_SUPPORT","type":"single_choice","title":"Nhà trường có nhu cầu tư vấn xây dựng phòng STEM không?","options":[{"id":"o_now","code":"now","label":"Có, trong năm học này","active":true},{"id":"o_later","code":"later","label":"Có, trong 1–2 năm tới","active":true},{"id":"o_no","code":"no","label":"Chưa có nhu cầu","active":true}],"logic":{"visibleIf":{"op":"and","rules":[{"questionId":"q_lab","operator":"equals","value":"no"}]}}},{"required":false,"id":"q_budget","code":"BUDGET","type":"single_choice","title":"Kinh phí dự kiến cho mỗi học sinh / năm","options":[{"id":"o_b1","code":"b1","label":"Dưới 300.000đ","active":true},{"id":"o_b2","code":"b2","label":"300.000 – 600.000đ","active":true},{"id":"o_b3","code":"b3","label":"600.000 – 1.000.000đ","active":true},{"id":"o_b4","code":"b4","label":"Trên 1.000.000đ","active":true},{"id":"o_b0","code":"b0","label":"Chưa xác định","active":true}]}]},{"id":"s_support","title":"Ưu tiên & góp ý","questions":[{"required":false,"id":"q_rank","code":"PRIORITIES","type":"ranking","title":"Xếp hạng mức độ ưu tiên hỗ trợ (1 = cao nhất)","options":[{"id":"o_teacher","code":"teacher","label":"Tập huấn giáo viên","active":true},{"id":"o_device","code":"device","label":"Thiết bị & bộ kit","active":true},{"id":"o_material","code":"material","label":"Học liệu, giáo án","active":true},{"id":"o_cost","code":"cost","label":"Chi phí hợp lý","active":true}]},{"required":false,"id":"q_interest","code":"INTEREST","type":"rating","title":"Mức độ quan tâm của nhà trường với giáo dục STEM","settings":{"scaleMax":5}},{"required":false,"id":"q_note","code":"COMMENTS","type":"long_text","title":"Đề xuất / góp ý thêm","placeholder":"Chủ đề khác, khó khăn hiện tại, mong muốn hỗ trợ…","validation":{"maxLength":2000}}]}]}'::jsonb, '{"preset":"education"}'::jsonb, '{"estimatedMinutes":8}'::jsonb, 'system'),
('course-satisfaction', 'Khảo sát hài lòng khóa học', 'Rating, ma trận đánh giá, Likert và NPS có câu hỏi phân nhánh.', 'Mức độ hài lòng', '{"schemaVersion":1,"sections":[{"id":"s1","title":"Đánh giá khóa học","questions":[{"required":true,"id":"q_course","code":"COURSE","type":"dropdown","title":"Khóa học bạn tham gia","options":[{"id":"o_c1","code":"c1","label":"Khóa A","active":true},{"id":"o_c2","code":"c2","label":"Khóa B","active":true},{"id":"o_c3","code":"c3","label":"Khóa C","active":true}],"settings":{"searchable":true}},{"required":true,"id":"q_overall","code":"OVERALL","type":"rating","title":"Đánh giá chung","settings":{"scaleMax":5}},{"required":false,"id":"q_mx","code":"ASPECTS","type":"matrix","title":"Đánh giá từng khía cạnh","rows":[{"id":"o_content","code":"content","label":"Nội dung","active":true},{"id":"o_teacher","code":"teacher","label":"Giảng viên","active":true},{"id":"o_facility","code":"facility","label":"Cơ sở vật chất","active":true},{"id":"o_org","code":"org","label":"Tổ chức","active":true}],"options":[{"id":"o_1","code":"1","label":"Kém","active":true},{"id":"o_2","code":"2","label":"Trung bình","active":true},{"id":"o_3","code":"3","label":"Tốt","active":true},{"id":"o_4","code":"4","label":"Rất tốt","active":true}]},{"required":false,"id":"q_lk","code":"APPLY","type":"likert","title":"Tôi có thể áp dụng kiến thức vào công việc","options":[{"id":"o_1","code":"1","label":"Rất không đồng ý","active":true},{"id":"o_2","code":"2","label":"Không đồng ý","active":true},{"id":"o_3","code":"3","label":"Trung lập","active":true},{"id":"o_4","code":"4","label":"Đồng ý","active":true},{"id":"o_5","code":"5","label":"Rất đồng ý","active":true}]},{"required":true,"id":"q_nps","code":"NPS","type":"nps","title":"Bạn có sẵn sàng giới thiệu khóa học cho đồng nghiệp?","settings":{"minLabel":"Không","maxLabel":"Chắc chắn"}},{"required":false,"id":"q_why","code":"NPS_REASON","type":"long_text","title":"Điều gì khiến bạn chưa hài lòng?","logic":{"visibleIf":{"op":"and","rules":[{"questionId":"q_nps","operator":"lte","value":6}]}}}]}]}'::jsonb, '{"preset":"feedback"}'::jsonb, '{"estimatedMinutes":3}'::jsonb, 'system'),
('event-registration', 'Đăng ký tham gia sự kiện', 'Thông tin liên hệ, vai trò, số người tham dự và xác nhận.', 'Đăng ký', '{"schemaVersion":1,"sections":[{"id":"s1","title":"Thông tin đăng ký","questions":[{"required":true,"id":"q_c","code":"CONTACT","type":"contact","title":"Thông tin người đăng ký","isPII":true,"settings":{"contactFields":["name","email","phone","organization"]}},{"required":true,"id":"q_role","code":"ROLE","type":"single_choice","title":"Bạn là","options":[{"id":"o_teacher","code":"teacher","label":"Giáo viên","active":true},{"id":"o_manager","code":"manager","label":"Cán bộ quản lý","active":true},{"id":"o_parent","code":"parent","label":"Phụ huynh","active":true},{"id":"o_student","code":"student","label":"Học sinh","active":true}],"settings":{"allowOther":true}},{"required":true,"id":"q_n","code":"ATTENDEES","type":"number","title":"Số người tham dự","validation":{"min":1,"max":20},"defaultValue":1},{"required":false,"id":"q_date","code":"SESSION_DATE","type":"date","title":"Ngày tham dự mong muốn"},{"required":true,"id":"q_ok","code":"CONSENT","type":"consent","title":"Xác nhận","settings":{"consentText":"Tôi đồng ý nhận thông tin về sự kiện qua email/điện thoại."}}]}]}'::jsonb, '{"preset":"event"}'::jsonb, '{"estimatedMinutes":2}'::jsonb, 'system')
